import {searchIntents} from './search-intents.mjs';
import {homeHTML} from './design.mjs';
import {tools,categories,featured,fresh,icon} from './catalog.mjs';
import {escapeHTML as e} from './core.mjs';
import {guideHTML} from './content.mjs';
import {pages} from './info.mjs';
import {blogIndex,blogCategories,blogHTML,blogCard} from './blog.mjs';
import {href,navHTML,starHTML,cardHTML,filteredTools} from './catalog-view.mjs';
export {href,navHTML,starHTML,cardHTML,filteredTools};
function taskShortcuts(){const priority=['images','fun','health','pregnancy','sports','nepal','study','education','business','pdf','audio','gaming','calculators'],all=categories.filter(c=>c.id!=='all'),card=c=>`<a href="${href('category',c.id)}"><span class="task-icon cat-${c.id}">${icon(c.icon)}</span><span><strong>${e(c.name)}</strong><small>${tools.filter(t=>t.category===c.id).length} useful tools</small></span>${icon('arrow')}</a>`;return `<section class="task-shortcuts" aria-label="Browse by task"><div class="section-head"><h2>What would you like to do?<small>A shortcut for every kind of day.</small></h2><span class="collection-badge">${all.length} collections</span></div><div class="task-grid">${priority.map(id=>card(all.find(c=>c.id===id))).join('')}</div><details class="more-collections"><summary>Explore ${all.length-priority.length} more collections ${icon('arrow')}</summary><div class="task-grid">${all.filter(c=>!priority.includes(c.id)).map(card).join('')}</div></details></section>`;}
function newCollectionHTML(){const ids=['anime-character','kids-worksheets','text-to-speech','qr-code'];return `<section class="discover-section"><div class="section-head"><h2>A little more possibility.<small>A little creativity. A little learning. More everyday possibility.</small></h2><a href="${href('catalog')}">Explore all ${tools.length} ${icon('arrow')}</a></div><div class="discover-grid">${ids.map((id,i)=>{const t=tools.find(t=>t.id===id);return `<a class="discover-card discover-${i}" href="${href('tool',id)}"><span class="discover-symbol" aria-hidden="true">${['✧','Aa','♪','▦'][i]}</span><span class="discover-label">${['MAKE A LITTLE CHARACTER','LEARN & PRACTICE','LISTEN & FOLLOW ALONG','CREATE & CONNECT'][i]}</span><h3>${e(t.title)}</h3><p>${e(t.description)}</p><span class="discover-arrow">${icon('arrow')}</span></a>`;}).join('')}</div></section>`;}
export const heroHTML=()=>`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>A little help for your everyday</div><h1>Little tools.<br><em>Big possibilities.</em></h1><p>For the things on your to-do list.<br>A thoughtful collection of ${tools.length} free tools to make<br class="desktop-br"> life a little easier.</p><div class="hero-actions"><a class="btn primary" href="${href('catalog')}">Explore the toolkit ${icon('arrow')}</a><span>${tools.length} tools. Zero fuss.</span></div></div><div class="hero-art" aria-label="Image converter and IELTS calculator previews"><span class="float-star" aria-hidden="true">✧</span><a class="float-card float-convert" href="${href('tool','image-converter')}"><div class="tiny-caption">A quick little conversion</div><div class="format-line"><span class="format-token">PNG</span>${icon('arrow')}<span class="format-token to">JPEG</span></div><div class="conversion-note">New format. Same great photo. ${icon('check')}</div></a><a class="float-card float-band" href="${href('tool','ielts-overall')}"><header><strong>IELTS overall band</strong><span class="tag">Try it out</span></header><div class="band-display"><b>7.5</b><div class="band-bars" aria-hidden="true"><i style="height:70%"></i><i style="height:85%"></i><i style="height:65%"></i><i style="height:100%"></i></div></div></a><div class="float-note"><span>↳</span>the little things, taken care of.</div></div></section><div class="trust-bar"><span>${icon('check')} Always free to use</span><span>${icon('shield')} Your files stay on your device</span><span>${icon('spark')} No sign-up. Just get going.</span></div>`;
function featuredHTML(){return `<section><div class="section-head"><h2>A few everyday favorites<small>Good places to start. Great things to get done.</small></h2><a href="${href('catalog')}">View all tools ${icon('arrow')}</a></div><div class="featured-grid">${featured.map((id,i)=>{const t=tools.find(t=>t.id===id);return`<a class="featured-card ${['mint','peach','lavender','blue'][i]}" href="${href('tool',id)}"><span class="feature-icon">${icon(t.icon)}</span><span class="small-arrow">${icon('arrow')}</span><h3>${e(t.title)}</h3><p>${e(t.description)}</p></a>`;}).join('')}</div></section>`;}
function creatorHTML(){return `<section class="creator-section"><div class="creator-intro"><div><span class="eyebrow"><span class="dot"></span>A fresh little spark</span><h2>Your new creative corner.</h2><p>From a screenshot to a shareable moment.<br>Useful tools for the things you’re making.</p></div><a class="btn secondary small" href="${href('category','creators')}">Open creator studio ${icon('arrow')}</a><div class="creator-doodle" aria-hidden="true"><span>✧</span><i>create.</i></div></div><div class="tool-grid creator-grid">${fresh.slice(0,4).map(id=>cardHTML(tools.find(t=>t.id===id))).join('')}</div></section>`;}
function educationHTML(){return `<section class="education-shortcuts"><div class="section-head"><h2>A little practice. A bright little day.<small>Choose a page, make it your own, then print or download.</small></h2></div><div class="featured-grid">${[['alphabet','Alphabet practice','A–Z, tracing and letter-finding.','book','mint'],['math','Math worksheets','Arithmetic practice and answer keys.','calculator','peach'],['handwriting','Handwriting sheets','Pale tracing words and writing guides.','type','lavender'],['coloring','Coloring pages','Six original pictures, ready for color.','palette','blue']].map(([id,title,description,symbol,tone])=>`<a class="featured-card ${tone}" href="${href('tool','kids-worksheets')}#${id}"><span class="feature-icon">${icon(symbol)}</span><h3>${title}</h3><p>${description}</p></a>`).join('')}</div></section>`;}
export function catalogHTML({home=false,category='all',query='',favorites=new Set(),layout='grid'}={}){if(home&&!query)return homeHTML(favorites,layout);const c=categories.find(c=>c.id===category),list=filteredTools(category,query,favorites),visible=home&&!query?list.slice(0,16):list,heading=query?`Results for “${e(query)}”`:category==='favorites'?'Your favorites':c?.name||'All tools';return `${home&&!query?heroHTML()+newCollectionHTML()+taskShortcuts()+featuredHTML()+creatorHTML():`<div class="page-heading"><div class="eyebrow"><span class="dot"></span>A little less busywork</div><h1>${heading}</h1><p>${category==='favorites'?'The shortcuts you want to keep close.':category==='creators'?'Make your next post, screenshot or idea a little more you.':'Useful tools, right when you need them. All free. All in your browser.'}</p></div>`}${category==='education'?educationHTML():''}<section id="all-tools"><div class="section-head"><h2>${home?'Your everyday toolkit':query?'Search results':'Pick a tool. Make it happen.'}</h2><span id="result-count" class="count-label">${list.length} ${list.length===1?'tool':'tools'}${query?' found':''}</span></div><form class="directory-search" data-tool-search role="search" action="./tools/" method="get"><label for="directory-query">Find a tool by name or task</label><div><span>${icon('search')}</span><input id="directory-query" name="q" type="search" value="${e(query)}" placeholder="Try pregnancy, cricket, photo booth or PDF…"><button class="btn primary" type="submit">Find tools ${icon('arrow')}</button></div></form><div class="tool-controls"><div class="chips-track" aria-label="Tool categories">${categories.map(c=>`<a class="chip ${category===c.id?'active':''}" href="${href(c.id==='all'?'catalog':'category',c.id)}">${c.id==='all'?'All tools':e(c.name.replace(' tools','').replace(' essentials',''))}</a>`).join('')}</div><div class="view-toggle"><button data-view="grid" class="${layout==='grid'?'active':''}" aria-label="Grid view" aria-pressed="${layout==='grid'}">${icon('grid')}</button><button data-view="list" class="${layout==='list'?'active':''}" aria-label="List view" aria-pressed="${layout==='list'}">${icon('list')}</button></div></div><div id="catalog-grid" class="tool-grid ${layout==='list'?'list':''}">${visible.length?visible.map(t=>cardHTML(t,favorites)).join(''):`<div class="empty-state">${icon(category==='favorites'?'star':'search')}<h3>${category==='favorites'&&!query?'Your own little toolkit.':'No tools found.'}</h3><p>${category==='favorites'&&!query?'Tap the star on any tool to keep it here.':'Try image, IELTS, PDF, meme, or calculator.'}</p>${query?'<button class="btn secondary small" data-clear-search>Clear search</button>':''}</div>`}</div>${home&&!query?`<div class="catalog-more"><a class="btn secondary" href="${href('catalog')}">Browse all ${tools.length} tools ${icon('arrow')}</a><p>Find your favorite by category, task or name.</p></div>`:''}</section>${home&&!query?`<section class="home-guides"><div class="section-head"><h2>A little know-how goes a long way.<small>Original guides for the things you’re making and calculating.</small></h2><a href="./blog/">Read all 35 guides ${icon('arrow')}</a></div><div class="blog-grid">${[blogIndex[0],blogIndex[8],blogIndex[27]].map(blogCard).join('')}</div></section>`:''}<aside class="bottom-note">${icon('shield')}<div><h3>Made for your work. Mindful of your privacy.</h3><p>Your images, documents and text are processed in your browser. We never upload your files.</p></div><span>No account needed.</span></aside>`;}
export function toolHTML(t,favorites=new Set()){const cat=categories.find(c=>c.id===t.category);return `<nav class="tool-breadcrumb" aria-label="Breadcrumb"><a href="${href('home')}">Home</a><span>/</span><a href="${href('category',t.category)}">${e(cat.name)}</a><span>/</span><span aria-current="page">${e(t.title)}</span></nav><div class="page-heading cat-${t.category}"><div class="tool-title-line"><span class="tool-icon">${icon(t.icon)}</span><h1>${e(searchIntents[t.id]?.heading||t.title)}</h1></div><p>${e(t.description)} Free, simple, and right here in your browser.</p></div><div class="tool-layout"><section class="tool-panel" id="tool-input" aria-label="${e(t.title)} inputs"><div class="result-placeholder">${icon(t.icon)}<span>Preparing your tool…</span><noscript>Enable JavaScript to run this tool locally in your browser.</noscript></div></section><section class="tool-panel" id="tool-result" aria-label="Tool result" aria-live="polite"><div class="result-placeholder">${icon(t.icon)}<strong>A little possibility, waiting.</strong><span>Your result will appear here.</span></div></section></div>${guideHTML(t)}${blogIndex.some(p=>p.tools.includes(t.id))?`<section class="related-guides"><div class="section-head"><h2>A little help with the next step.</h2><a href="./blog/">All guides ↗</a></div><div class="blog-grid">${blogIndex.filter(p=>p.tools.includes(t.id)).slice(0,3).map(blogCard).join('')}</div></section>`:''}<div class="section-head"><h2>A little more in your toolkit</h2><a href="${href('category',t.category)}">See the category ${icon('arrow')}</a></div><div class="tool-grid">${tools.filter(x=>(x.category===t.category||t.category==='education'&&['typing-test','flashcards','text-to-speech'].includes(x.id))&&x.id!==t.id).slice(0,3).map(t=>cardHTML(t,favorites)).join('')}</div>`;}
export function parsePage(pathname,base='/'){let path=pathname.startsWith(base)?pathname.slice(base.length):pathname.replace(/^\//,'');path=path.replace(/index\.html$/,'').replace(/^\/|\/$/g,'');const p=path.split('/');if(!path)return{type:'home'};if(p[0]==='blog'&&p.length===1)return{type:'blog'};if(p[0]==='blog'&&p.length===2&&blogIndex.some(b=>b.slug===p[1]))return{type:'article',id:p[1]};if(p[0]==='blog'&&p[1]==='category'&&p.length===3&&blogCategories.some(c=>c[0]===p[2]))return{type:'blogCategory',id:p[2]};if(p[0]==='tools'&&p.length===2&&p[1])return tools.some(t=>t.id===p[1])?{type:'tool',id:p[1]}:{type:'notfound'};if(p[0]==='tools'&&p.length===1)return{type:'catalog'};if(p.length===2&&p[0]==='categories'&&categories.some(c=>c.id===p[1]&&c.id!=='all'))return{type:'category',id:p[1]};if(p.length===1&&p[0]==='favorites')return{type:'favorites'};if(p.length===1&&pages[p[0]])return{type:p[0]};return{type:'notfound'};}
export function pageHTML(page,options={}){if(['blog','blogCategory','article'].includes(page.type))return blogHTML(page,options.article);if(page.type==='tool')return toolHTML(tools.find(t=>t.id===page.id),options.favorites);if(['home','catalog','category','favorites'].includes(page.type))return catalogHTML({home:page.type==='home',category:page.type==='favorites'?'favorites':page.type==='category'?page.id:'all',...options});if(pages[page.type])return `<article class="legal">${pages[page.type]}</article>`;return `<div class="empty-state"><h1>A little off the map.</h1><p>We couldn’t find that page. Your next useful tool is still here.</p><a class="btn primary" href="${href('catalog')}">Explore all tools ${icon('arrow')}</a></div>`;}
